export type PRODUCT =
  | PRODUCT_SHORTNAMES.DATABASE
  | PRODUCT_SHORTNAMES.AUTHENTICATION
  | PRODUCT_SHORTNAMES.STORAGE
  | PRODUCT_SHORTNAMES.FUNCTIONS
  | PRODUCT_SHORTNAMES.COMPUTE
